        #region btnPopulateRates_Click
        private void btnPopulateRates_Click(object sender, EventArgs e)
        {
            try
            {
                this.Cursor = Cursors.WaitCursor;
                    Income_NonIncomeTax_ReUpdating();
                this.Cursor = Cursors.Default;
            }
            catch(Exception err)
            {
                this.Cursor = Cursors.Default;
                cmnService.J_UserMessage(err.Message);
            }
        }
